import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { verifyDevice } from '../src/device-auth.js';

test('Windows CNG P1363 signature verifies in Web Crypto with no private key', async () => {
  // Generated by the desktop self-check using a transient non-exportable CNG key,
  // which was deleted immediately afterwards. This contains public data only.
  const f = JSON.parse(await readFile(new URL('./fixtures/cng-request.json', import.meta.url), 'utf8'));
  const request = new Request(`${f.origin}/device/${f.user}/poll`, { method: 'POST', headers: {
    'X-Pilot-Timestamp': f.timestamp, 'X-Pilot-Nonce': f.nonce, 'X-Pilot-Signature': f.signature
  }, body: f.body });
  const state = { publicKey: f.publicKey, user: f.user, keyExpires: Number(f.timestamp) + 60_000, nonces: [] };
  assert.ok(await verifyDevice(request, f.body, state, f.origin, 'poll', Number(f.timestamp)));
  assert.equal(await verifyDevice(request, f.body + ' ', state, f.origin, 'poll', Number(f.timestamp)), null);
});
